const express = require('express');
const { stagingUserAuth } = require('../auth/staging');
const { FixtureDatabase } = require('../db/fixtures');

const app = express();
app.use(express.json());

app.post('/staging/api/fixtures/:targetOrgId/reseed', stagingUserAuth, async (req, res) => {
  const { targetOrgId } = req.params;
  const { fixtureProfile } = req.body;

  // Ensure caller is an administrator of the target staging tenant
  if (req.user.role !== 'STAGING_PLATFORM_ADMIN' && req.user.orgId !== targetOrgId) {
    return res.status(403).json({ error: 'Access denied: Cannot reseed staging fixtures for other organizations' });
  }

  const exists = await FixtureDatabase.tenantExists(targetOrgId);
  if (!exists) {
    return res.status(404).json({ error: 'Staging tenant organization not found' });
  }

  await FixtureDatabase.resetAndSeed(targetOrgId, fixtureProfile || 'standard_seed');
  res.json({ success: true, message: `Staging environment for ${targetOrgId} reseeded` });
});

module.exports = app;
